def shunting_yard(expr={{expr}}):
    prec = {'+':1, '-':1, '*':2, '/':2, '^':3}
    right_assoc = {'^'}
    out = []; ops = []
    tokens = expr.replace('(', ' ( ').replace(')', ' ) ').split()
    for tok in tokens:
        if tok.replace('.', '', 1).isdigit():
            out.append(tok)
        elif tok in prec:
            while ops and ops[-1] != '(' and (prec[ops[-1]] > prec[tok] or (prec[ops[-1]] == prec[tok] and tok not in right_assoc)):
                out.append(ops.pop())
            ops.append(tok)
        elif tok == '(':
            ops.append(tok)
        elif tok == ')':
            while ops and ops[-1] != '(': out.append(ops.pop())
            ops.pop()
    while ops: out.append(ops.pop())
    return out
